css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 8px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-family: sans-serif; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; margin-bottom: 5px;}
.mz .recuerda-grid{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px;}
.mz .recuerda-item{display: flex; flex-direction: column; gap: 2px; border-left: 2px solid var(--bosque); padding-left: 7px;}
.mz .recuerda-tipo{font-size: 13px; font-weight: 700;}
.mz .recuerda-def{font-size: 12px; font-weight: 600; line-height: 1.3;}
.mz .recuerda-ej{font-family: sans-serif; font-size: 10px; color: #444; font-style: italic;}
.mz .banco-palabras{display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px;}
.mz .palabra-chip{font-size: 14px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 2px 10px;}
.mz .tabla-clasificar{width: 100%; border-collapse: collapse; margin-bottom: 10px;}
.mz .tabla-clasificar th{font-size: 13px; font-weight: 700; padding: 5px 8px; border: 1.5px solid var(--bosque); text-align: center;}
.mz .tabla-clasificar td{height: 28px; border: 1.5px solid var(--bosque); padding: 3px 8px;}
.mz .frases-lista{display: flex; flex-direction: column; gap: 7px; margin-bottom: 10px;}
.mz .frase-item{font-size: 15px; font-weight: 600; line-height: 1.5;}
.mz .frase-num{font-family: sans-serif; font-size: 12px; font-weight: 700; margin-right: 4px;}
.mz .escribir-lineas{display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px;}
.mz .escribir-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .frase-item,.mz .recuerda-def{line-height: 1.725 !important;}
